  ],
  "contradictory_card_ids": ["C81"],
  "prediction_basis_card_ids": [
    "C48","C54","C55","C58","C50","C61","C62","C67","C70",
    "C59","C60","C63","C64","C68","C69",
    "C01","C05","C16","C04","C07","C09","C13","C08","C18",
    "C03","C15","C02","C12","C10","C11"
  ],
  "claims": [
    {
      "claim": "The query is a 1272 Da, fully ionized corrinoid-nucleotide phosphodiester (logD -3.35, TPSA 460 A^2, 11 HBD, 19 HBA); no direct oral bioavailability measurement exists for it.",
      "card_ids": []
    },
    {
      "claim": "Human B12/corrinoid absorption records show only about 1-5% oral absorption for cyanocobalamin, and Caco-2 Papp for cyanocobalamin is 0.1 x 10^-6 cm/s with efflux ratio 1.0, supporting very low intestinal absorption for the corrinoid scaffold.",
      "card_ids": ["C48","C54","C55","C58","C50","C61","C62","C67","C70"]
    },
    {
      "claim": "Other large/polar molecules show similarly low Caco-2 permeability (tenofovir 0.15 x 10^-6 cm/s, acteoside 0.24-0.34 x 10^-6 cm/s, paeoniflorin 0.48 x 10^-6 cm/s, holotoxin below detection, So324 0.7 x 10^-6 cm/s), reinforcing that extreme size and polarity yield very low intestinal permeability.",
      "card_ids": ["C59","C60","C63","C64","C68","C69"]
    },
    {
      "claim": "L1/L2 human low-F records for polar/nucleotide-like molecules (ATP 3.2-14.9%, saquinavir 4%, THU 4.1%, gemcitabine ~10%, levovirin ~10%, didanosine 17%, R1479 6-18%, phlorizin poor) are consistent with low F for this class.",
      "card_ids": ["C04","C07","C09","C13","C08","C18","C03","C15","C02","C12","C10","C11","C01","C05","C16"]
    },
    {
      "claim": "L6 C81 shows the query-like corrinoid M04 has a human liver microsome metabolic half-life >120 min, indicating high metabolic stability; this is a positive factor but does not address the absorption barrier.",
      "card_ids": ["C81"]
    },
    {
      "claim": "Other L6 records concern zidovudine UGT glucuronidation, capecitabine CES/CDA clearance, and a sildenafil metabolite; they are not applicable to the query scaffold.",
      "card_ids": ["C72","C77","C78","C79","C82","C71","C73","C74","C75","C76","C80"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "contradictory",
      "decision_effect": "weakened",
      "card_ids": ["C81"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability or query-specific absorption measurement exists; the low prediction relies on transfer from B12/corrinoid and other polar-molecule records plus physicochemical priors.",
    "B12 absorption is partly receptor-mediated; the query lacks cobalt and may not engage intrinsic-factor/cubilin uptake, so the exact absorption mechanism and dose dependence are uncertain.",
    "C81 is an in vitro microsomal stability measurement, not in vivo hepatic clearance or F; high metabolic stability does not quantify absorption or systemic availability.",
    "No query-specific formulation, dose, species, or human PK data are available; formulation-dependent absorption cannot be fully excluded.",
    "L6 records for zidovudine, capecitabine, and sildenafil metabolite are not transferable to the query scaffold."
  ],
  "decision_summary": "L6 adds one relevant record (C81) showing the query-like corrinoid M04 is metabolically stable in human liver microsomes (>120 min), which mildly weakens the low prediction by removing hepatic first-pass as a major loss mechanism, but it does not overcome the strong absorption barrier; L4/L5 corrinoid/B12 permeability and absorption evidence plus physicochemical priors affirmatively support F < 20%, so prediction remains low with high confidence."
}

